$$
\begin{array}{c} C _ {\mathrm{L}} = 1. 2 8 \frac {\alpha_ {\mathrm{H}}}{| \alpha_ {\mathrm{H}} |} \cos \alpha_ {\mathrm{H}} \\ C _ {\mathrm{D}} = 1. 2 8 \frac {\alpha_ {\mathrm{H}}}{| \alpha_ {\mathrm{H}} |} \sin \alpha_ {\mathrm{H}} \\ F _ {\mathrm{n}} = - \left[ C _ {\mathrm{L}} \cos (\alpha_ {\mathrm{H}} + \alpha_ {\mathrm{H0}}) + C _ {\mathrm{D}} \sin (\alpha_ {\mathrm{H}} + \alpha_ {\mathrm{H0}}) \right] q S _ {\mathrm{H}} \end{array}
